  3	// Remembered spools, a fork-owned concept OrcaSlicer does not have.
  4	//
  5	// Orca knows filament presets and one colour per extruder in the project
  6	// config. It has no idea that the same PLA+ preset in white and in black are
  7	// two physical reels a person swaps between. A spool is that pairing, named by
  8	// the person who owns it, remembered per printer.
  9	//
 10	// Machine facts are app-level, not project-level, so this lives beside the
 11	// application data rather than inside the 3mf: a project opened on another
 12	// machine describes the same print, not the same shelf of filament.
 13	//
 14	// GUI-free and Orca-free: the store holds preset *names* and hex strings, so
 15	// it can be tested without wx, a PresetBundle, or a data directory. Selecting
 16	// a spool -- which does touch Orca -- belongs to Shell/SetupCommands.
 17	
 18	#include <cstdint>
 19	#include <functional>
 20	#include <optional>
 21	#include <string>
 22	#include <vector>
 23	
 24	namespace Slic3r::GUI::JusPrin::Workspace {
 25	
 26	struct Spool
 27	{
 28	    std::string id;              // opaque, unique within the store
 29	    std::string printer_preset;  // Orca printer preset this spool belongs to
 30	    std::string filament_preset; // Orca filament preset name
 31	    std::string colour;          // "#RRGGBB"
 32	    std::string name;            // user-visible and editable
 33	    std::string brand;           // vendor cached from the preset at creation
 34	    std::string last_used;       // ISO-8601 UTC
 35	
 36	    bool operator==(const Spool& rhs) const
 37	    {
 38	        return id == rhs.id && printer_preset == rhs.printer_preset && filament_preset == rhs.filament_preset &&
 39	               colour == rhs.colour && name == rhs.name && brand == rhs.brand && last_used == rhs.last_used;
 40	    }
 41	};
 42	
 43	// A JSON file of spools, loaded once at construction and written through on
 44	// every mutation. Small by design: a person keeps three to fifteen spools, so
 45	// there is no index, no cache, and no partial write.
 46	class SpoolStore
 47	{
 48	public:
 49	    struct Config
 50	    {
 51	        // Absolute path of the JSON file. Required.
 52	        std::string file_path;
 53	        // Injectable for deterministic tests.
 54	        std::function<std::string()> clock; // ISO-8601 UTC timestamp
 55	        std::function<std::string()> uuid;  // opaque unique identifier
 56	    };
 57	
 58	    // Reads the file. A missing file is an empty store, which is the ordinary
 59	    // first-run state.
 60	    //
 61	    // A file that exists but does not parse is moved aside to
 62	    // "<file_path>.corrupt" and the store starts empty. Overwriting it would
 63	    // destroy spools the person named by hand, and refusing to start would
 64	    // take the chip down over a file the product can rebuild by seeding. The
 65	    // move is reported through corrupt(), so the state stays visible rather
 66	    // than being logged and forgotten.
 67	    explicit SpoolStore(Config config);
 68	
 69	    SpoolStore(const SpoolStore&) = delete;
 70	    SpoolStore& operator=(const SpoolStore&) = delete;
 71	
 72	    // True when the backing file existed, could not be parsed, and was moved
 73	    // aside by this constructor.
 74	    bool               corrupt() const { return m_corrupt; }
 75	    const std::string& corrupt_reason() const { return m_corrupt_reason; }
 76	
 77	    // Every spool for this printer, most recently used first. Ties break on
 78	    // id so the order is stable across runs.
 79	    std::vector<Spool> spools_for(const std::string& printer_preset) const;
 80	
 81	    // The spool whose filament preset and colour both match what the project
 82	    // currently has loaded, or nothing when the project does not correspond to
 83	    // a remembered spool.
 84	    std::optional<Spool> current(const std::string& printer_preset,
 85	                                 const std::string& filament_preset,
 86	                                 const std::string& colour) const;
 87	
 88	    std::optional<Spool> find(const std::string& id) const;
 89	
 90	    // Assigns id and last_used, stores, and returns the stored record.
 91	    Spool add(Spool spool);
 92	
 93	    // Each returns false when the id is unknown; the caller owns the decision
 94	    // about a stale menu, so an unknown id is a normal answer here rather than
 95	    // an error.
 96	    bool rename(const std::string& id, const std::string& name);
 97	    bool recolour(const std::string& id, const std::string& colour);
 98	    bool remove(const std::string& id);
 99	    bool touch(const std::string& id);
100	
101	    // A printer is its Orca printer preset, so renaming the preset moves its
102	    // spools and removing it takes them along. Each returns how many spools
103	    // changed; a printer with none is a normal answer.
104	    std::size_t move_printer(const std::string& from, const std::string& to);
105	    std::size_t remove_printer(const std::string& printer_preset);
106	
107	    std::size_t size() const { return m_spools.size(); }
108	
109	private:
110	    // Write temp, rename over. Throws when the write fails: a spool the person
111	    // just named must not silently fail to persist.
112	    void write();
113	
114	    Config             m_config;
115	    std::vector<Spool> m_spools;
116	    bool               m_corrupt{false};
117	    std::string        m_corrupt_reason;
118	};
