177	PrintActionState StatusRow::action_state() const
178	{
179	    PrintActionState state;
180	    auto& plates = m_plater.get_partplate_list();
181	    auto* plate = plates.get_curr_plate();
182	    state.slicing = m_plater.is_background_process_slicing();
183	    state.plate_number = plates.get_curr_plate_index() + 1;
184	    state.plate_count = plates.get_plate_count();
185	    const bool editable = !m_plater.only_gcode_mode() && !m_plater.using_exported_file();
186	    for (int i = 0; i < state.plate_count; ++i) {
187	        auto* item = plates.get_plate(i);
188	        if (item->is_slice_result_valid()) ++state.sliced_count;
189	        if (editable && item->can_slice() && !item->is_slice_result_valid()) state.can_slice_all = true;
190	    }
191	    if (plate) {
192	        state.sliced = plate->is_slice_result_valid();
193	        state.can_slice = editable && plate->can_slice();
194	        state.can_print = plate->is_slice_result_ready_for_print();
195	        state.can_export = plate->is_slice_result_ready_for_export();
196	    }
197	    auto* presets = wxGetApp().preset_bundle;
198	    // Match the native print-all backend support. Other legacy hosts accept
199	    // only one plate, even when several valid slices exist.
200	    bool supports_all = presets && presets->use_bbl_network();
201	    if (presets && !supports_all) {
202	        const auto& config = presets->printers.get_edited_preset().config;
203	        const auto* host = config.option<ConfigOptionEnum<PrintHostType>>("host_type");
204	        supports_all = host && host->value == htSimplyPrint;
205	    }
206	    state.can_print_all = supports_all && plates.is_all_slice_results_ready_for_print();
207	    return state;
208	}
