210	wxString StatusRow::action_label(PrintAction action, bool primary) const
211	{
212	    const auto state = action_state();
213	    switch (action) {
214	    case PrintAction::Slice: return _L("Slice");
215	    case PrintAction::SliceAll: return _L("Slice all plates");
216	    case PrintAction::Cancel: return primary ? _L("Slicing…") : _L("Cancel");
217	    case PrintAction::Print: return primary ? (state.plate_count > 1 ? wxString::Format(_L("Print plate %d"), state.plate_number) : _L("Print")) : _L("Print…");
218	    case PrintAction::PrintAll: return _L("Print all plates…");
219	    case PrintAction::Export: return _L("Export sliced file…");
220	    }
221	    throw std::logic_error("Unknown print action");
222	}
