224	std::tuple<std::uint64_t, std::uint64_t, std::uint64_t> StatusRow::print_target_identity() const
225	{
226	    auto* plate = m_plater.get_partplate_list().get_curr_plate();
227	    return {m_plater.project_state_session(), plate ? plate->id().id : 0,
228	            plate && plate->is_slice_result_valid() && !m_plater.is_background_process_slicing() && plate->get_slice_result() ?
