232	void StatusRow::show_action_menu()
233	{
234	    const auto identity = print_target_identity();
235	    const auto state = action_state();
236	    const auto actions = primary_print_action(state);
237	    std::vector<HeaderMenuItem> menu;
238	    for (const auto& item : actions.menu) {
239	        HeaderIcon icon = HeaderIcon::Slice;
240	        if (item.action == PrintAction::Print) icon = HeaderIcon::Print;
241	        else if (item.action == PrintAction::PrintAll || item.action == PrintAction::SliceAll) icon = HeaderIcon::Plates;
242	        else if (item.action == PrintAction::Export) icon = HeaderIcon::Export;
243	        else if (item.action == PrintAction::Cancel) icon = HeaderIcon::Cancel;
244	        wxString detail;
245	        if (item.action == PrintAction::PrintAll)
246	            detail = wxString::Format(_L("%d sliced"), state.sliced_count);
247	        menu.push_back({action_label(item.action), icon, detail, item.enabled, item.action == PrintAction::Export,
248	            [this,identity,action=item.action] {
249	                // The menu describes one plate/result. A later plate switch or
250	                // project replacement must not retarget that displayed command.
251	                if (print_target_identity() == identity) request_action(action);
252	            }});
253	    }
254	    if (!menu.empty()) (new HeaderMenu(this,m_theme,m_dark,std::move(menu)))->open(*m_menu_button);
255	}
