294	        place(m_menu_button,right);
295	    }
296	    right -= m_slice_button->GetBestSize().x;
297	    place(m_slice_button,right);
298	    place(m_home_button,margin);
299	    const int left = margin+m_home_button->GetBestSize().x+gap;
300	    const int available = std::max(0,right-gap-left);
301	    const int width = std::min(m_chip->GetBestSize().x,available);
302	    const wxSize chip = m_chip->GetBestSize();
303	    m_chip->SetSize(left+(available-width)/2,(height-chip.y)/2,width,chip.y);
304	}
