350	// The chip renders Orca's authoritative selection plus the spool the store
351	// remembers for it. Nothing here writes; a swap goes through SetupCommands.
352	void StatusRow::refresh_chip()
353	{
354	    const auto printer = SetupCommands::current_printer();
355	    m_chip->set_printer(printer.nickname, printer.valid ? wxString::Format("%g", printer.nozzle) : wxString{});
356	    if (printer.extruder_count > 1) {
357	        // TODO(slice 2): multi-extruder printers show extruder 0 only. Slot
358	        // mapping, the AMS chip, and multi-colour projects are a separate
359	        // brief; the chip must not imply it is describing every extruder.
360	    }
361	
362	    const auto     filament = SetupCommands::current_filament();
363	    const wxString colour   = SetupCommands::current_colour();
364	    const wxColour parsed(colour);
365	    const auto     spool    = current_spool();
366	    m_chip->set_spool(spool ? wxString::FromUTF8(spool->name) : filament.alias, parsed);
367	}
