454	void StatusRow::request_action(PrintAction action)
455	{
456	    const auto actions = primary_print_action(action_state());
457	    const auto eligible = [action](const PrintActionItem& item) { return item.action == action && item.enabled; };
458	    if (!eligible(actions.primary) && std::none_of(actions.menu.begin(), actions.menu.end(), eligible)) return;
459	    switch (action) {
460	    case PrintAction::Slice: request_slice(); return;
461	    case PrintAction::SliceAll: request_slice(true); return;
462	    case PrintAction::Cancel: m_plater.cancel_slicing(); return;
463	    case PrintAction::Print:
464	    case PrintAction::PrintAll: {
465	        auto& presets = *wxGetApp().preset_bundle;
466	        const auto* host = presets.printers.get_edited_preset().config.option<ConfigOptionString>("print_host");
467	        if (!presets.use_bbl_network() && (!host || host->value.empty())) {
468	            wxMessageBox(_L("Configure a printer connection in Printer settings before printing. You can also export the sliced file."),
469	                         _L("Printer connection required"), wxOK | wxICON_INFORMATION, this);
470	            return;
471	        }
472	        SimpleEvent event(action == PrintAction::Print ? EVT_GLTOOLBAR_PRINT_PLATE : EVT_GLTOOLBAR_PRINT_ALL);
473	        m_plater.GetEventHandler()->ProcessEvent(event); // native confirmation; never an upload shortcut
474	        return;
475	    }
476	    case PrintAction::Export: {
477	        SimpleEvent event(EVT_GLTOOLBAR_EXPORT_SLICED_FILE);
478	        m_plater.GetEventHandler()->ProcessEvent(event);
479	        return;
480	    }
481	    }
482	}
