484	void StatusRow::request_slice(bool all)
485	{
486	    const auto state = action_state();
487	    if (state.slicing || state.sliced || (all ? !state.can_slice_all : !state.can_slice)) return;
488	    m_plater.exit_gizmo();
489	    m_plater.update(true, true);
490	    request_prepare();
491	    SimpleEvent event(all ? EVT_GLTOOLBAR_SLICE_ALL : EVT_GLTOOLBAR_SLICE_PLATE);
492	    m_plater.GetEventHandler()->ProcessEvent(event);
493	    refresh();
494	}
