144	// Right-aligned transient menu. The popup owns only presentation; callbacks
145	// return to the owner after dismissal, never run commands inside mouse capture.
146	//
147	// A menu can also replace its own contents in place -- the spool menu's
148	// "Other spool…" view does this rather than opening a second popup, so the
149	// popup keeps its position, its keyboard model, and its dismissal handling.
150	class HeaderMenu : public PopupWindow
151	{
152	public:
153	    HeaderMenu(wxWindow* parent, const ShellTheme& theme, bool dark,
154	               std::vector<HeaderMenuItem> items);
155	    void open(HeaderButton& anchor);
156	    HeaderButton* selected_item() const { return m_selected < 0 ? nullptr : m_items[m_selected]; }
157	
158	    // Swaps the rows for a new set and re-lays out at the same anchor. The
159	    // width stays put so the popup does not jump as the person types.
160	    void replace_items(std::vector<HeaderMenuItem> items);
161	    // A custom view above the rows -- the search field of the "Other spool…"
162	    // step. The builder runs with the popup as parent; nullptr clears it.
163	    // `after_rows` places the custom view below that many rows, so a step can
164	    // keep its title/back row at the top where the design puts it.
165	    void set_header_builder(std::function<wxWindow*(wxWindow*)> builder, int after_rows = 0);
166	    // Invoked when the popup dismisses for any reason, after the anchor has
167	    // been released. Used to drop menu-owned state the owner is holding.
168	    void set_dismiss_listener(std::function<void()> listener) { m_dismissed = std::move(listener); }
169	
170	    // Dismisses the popup and releases its anchor. Public because closing a
171	    // menu is a normal thing for an owner (or a test) to ask for; Dismiss()
172	    // alone would leave the anchor painting its open state.
173	    void close();
174	
175	protected:
176	    void OnDismiss() override;
177	
178	private:
179	    void select_item(int index);
180	    void build(std::vector<HeaderMenuItem> items);
181	    void on_key(wxKeyEvent& event);
182	    void reposition();
183	
184	    const ShellTheme& m_theme;
185	    bool m_dark{false};
186	    std::vector<HeaderButton*> m_items;
187	    wxWindow* m_header{nullptr};
188	    std::function<wxWindow*(wxWindow*)> m_header_builder;
189	    int m_header_after_rows{0};
190	    std::function<void()> m_dismissed;
191	    wxWeakRef<HeaderButton> m_anchor;
192	    bool m_closed{false};
193	    int m_selected{-1};
194	    int m_width{0};
195	};
