14	// Small semantic strokes share the header's foreground and DPI transform.
15	void draw_icon(wxGraphicsContext& gc, HeaderIcon icon, double x, double y, double size, const wxColour& color)
16	{
17	    gc.PushState();
18	    gc.Translate(x, y);
19	    gc.Scale(size / 16., size / 16.);
20	    gc.SetPen(wxPen(color, 1));
21	    gc.SetBrush(*wxTRANSPARENT_BRUSH);
22	    auto line = [&](std::initializer_list<wxPoint2DDouble> points) {
23	        auto path = gc.CreatePath();
24	        bool first = true;
25	        for (const auto& p : points) {
26	            if (first) path.MoveToPoint(p.m_x, p.m_y);
27	            else path.AddLineToPoint(p.m_x, p.m_y);
28	            first = false;
29	        }
30	        gc.StrokePath(path);
31	    };
32	    switch (icon) {
33	    case HeaderIcon::Back: line({{10,3},{5,8},{10,13}}); break;
34	    case HeaderIcon::Right: line({{6,3},{11,8},{6,13}}); break;
35	    case HeaderIcon::Down: line({{4,6},{8,10},{12,6}}); break;
36	    case HeaderIcon::Up: line({{4,10},{8,6},{12,10}}); break;
37	    case HeaderIcon::Check: line({{3,8.5},{6.5,12},{13,4}}); break;
38	    case HeaderIcon::Caret: {
39	        // A filled disclosure triangle, as the chip halves use in the design.
40	        auto p = gc.CreatePath();
41	        p.MoveToPoint(4.5,6.5); p.AddLineToPoint(11.5,6.5); p.AddLineToPoint(8,10.5); p.CloseSubpath();
42	        gc.SetBrush(wxBrush(color)); gc.SetPen(*wxTRANSPARENT_PEN);
43	        gc.FillPath(p);
44	        break;
45	    }
46	    case HeaderIcon::Printer:
47	        // A printer: paper feeding out of a body, not the abstract mark the
48	        // previous single chip inherited.
49	        line({{4.5,6},{4.5,2.5},{11.5,2.5},{11.5,6}});
50	        line({{2.5,6},{13.5,6},{13.5,11},{2.5,11},{2.5,6}});
51	        line({{4.5,9},{4.5,13.5},{11.5,13.5},{11.5,9}});
52	        break;
53	    case HeaderIcon::Monitor:
54	        line({{2,3},{14,3},{14,11},{2,11},{2,3}});
55	        line({{6,14},{10,14}}); line({{8,11},{8,14}});
56	        break;
57	    case HeaderIcon::More:
58	        gc.SetBrush(wxBrush(color));
59	        for (int i = 0; i < 3; ++i) gc.DrawEllipse(3 + i * 4, 7, 1.5, 1.5);
60	        break;
61	    case HeaderIcon::Cancel: line({{4,4},{12,12}}); line({{12,4},{4,12}}); break;
62	    case HeaderIcon::Slice:
63	        gc.DrawEllipse(1.5,1.5,13,13);
64	        line({{6,4.5},{11,8},{6,11.5},{6,4.5}});
65	        break;
66	    case HeaderIcon::Plates:
67	        line({{2,5},{8,2},{14,5},{8,8},{2,5}});
68	        line({{2,8},{8,11},{14,8}}); line({{2,11},{8,14},{14,11}}); break;
69	    case HeaderIcon::Export:
70	        line({{8,2},{8,9.5}}); line({{4.5,6},{8,9.5},{11.5,6}});
71	        line({{3,11},{3,13.5},{13,13.5},{13,11}}); break;
72	    case HeaderIcon::Print:
73	        line({{2,7},{14,2},{9,14},{7,9},{2,7}}); line({{7,9},{14,2}}); break;
74	    case HeaderIcon::PanelOpen:
75	    case HeaderIcon::PanelClosed:
76	        line({{2.5,3.5},{13.5,3.5},{13.5,12.5},{2.5,12.5},{2.5,3.5}});
77	        line({{9.5,3.5},{9.5,12.5}});
78	        if (icon == HeaderIcon::PanelOpen) {
79	            gc.SetBrush(wxBrush(color));
80	            gc.SetPen(*wxTRANSPARENT_PEN);
81	            gc.DrawRectangle(9.5,3.5,4,9);
82	        }
83	        break;
84	    case HeaderIcon::None: break;
85	    }
86	    gc.PopState();
87	}
