89	wxColour status_colour(StatusTone tone, const ShellPalette& p)
90	{
91	    switch (tone) {
92	    case StatusTone::Positive: return p.status_success;
93	    case StatusTone::Busy:     return p.action_primary;
94	    case StatusTone::Warning:  return p.status_warning;
95	    case StatusTone::Neutral:  return p.text_secondary;
96	    case StatusTone::None:     break;
97	    }
98	    return p.text_secondary;
99	}
