222	// How much of a row's width is reserved on the right for everything that is
223	// not the label. Shared by the size calculation and the painter so a row can
224	// never measure one way and paint another.
225	int HeaderButton::trailing_reserve() const
226	{
227	    int reserve = FromDIP(12);
228	    if (m_row_action != HeaderIcon::None) reserve += FromDIP(20);
229	    if (m_status) reserve += FromDIP(16);
230	    if (m_decoration.check) reserve += FromDIP(20);
231	    if (m_decoration.trailing != HeaderIcon::None) reserve += FromDIP(20);
232	    if (m_decoration.status != StatusTone::None) {
233	        reserve += FromDIP(14); // dot and its gap
234	        if (!m_decoration.status_word.empty()) reserve += GetTextExtent(m_decoration.status_word).x + FromDIP(4);
235	    }
236	    if (!m_decoration.detail.empty() && !m_decoration.detail_inline) {
237	        wxClientDC dc(const_cast<HeaderButton*>(this));
238	        dc.SetFont(detail_font());
239	        reserve += dc.GetTextExtent(m_decoration.detail).x + FromDIP(16);
240	    }
241	    return reserve;
242	}
