244	wxSize HeaderButton::DoGetBestSize() const
245	{
246	    const ShellMetrics& m = m_theme.metrics();
247	    // No recipe covers a split action: its arrow half is the functional icon
248	    // plus a 12 DIP gutter, as tall as the status row it lives in.
249	    if (m_style == HeaderStyle::PrimaryRight) return FromDIP(wxSize(m.button.icon.icon_size + m.space_3, m.status_row.height));
250	    if (m_style == HeaderStyle::Outline) return FromDIP(wxSize(m.button.icon.width, m.button.icon.height));
251	    int label = GetTextExtent(GetLabel()).x;
252	    if (!m_decoration.sub_label.empty()) {
253	        wxClientDC dc(const_cast<HeaderButton*>(this));
254	        dc.SetFont(m_theme.font(TextRole::Metadata));
255	        label = std::max(label, dc.GetTextExtent(m_decoration.sub_label).x);
256	    }
257	    if (m_label_cap > 0) label = std::min(label, FromDIP(m_label_cap));
258	    if (!m_decoration.detail.empty() && m_decoration.detail_inline) {
259	        wxClientDC dc(const_cast<HeaderButton*>(this));
260	        dc.SetFont(detail_font());
261	        // Measured exactly as painted: " \xC2\xB7" plus a 3 DIP gap, or the chip
262	        // reserves space it never fills and the chevron drifts right.
263	        label += dc.GetTextExtent(wxString::FromUTF8(" \xC2\xB7")).x + FromDIP(3) +
264	                 dc.GetTextExtent(m_decoration.detail).x;
265	    }
266	    const int leading = FromDIP(12) + (m_icon == HeaderIcon::None ? 0 : FromDIP(24)) +
267	                        (m_decoration.dot.has_value() ? FromDIP(16) : 0);
268	    // A two-line row is one spacing step taller than the menu row recipe;
269	    // the print action and the quiet buttons fill the status row.
270	    const int height = m_style == HeaderStyle::Menu ? (m_decoration.sub_label.empty() ? m.menu_row.height : m.menu_row.height + m.space_3) :
271	                       m_style == HeaderStyle::ChipLeft || m_style == HeaderStyle::ChipRight ? m.chip.height : m.status_row.height;
272	    return {leading + label + trailing_reserve(), FromDIP(height)};
273	}
