300	void HeaderButton::draw(wxDC& dc, wxGraphicsContext& context, const wxSize& client)
301	{
302	    const auto& p = m_theme.palette(m_dark);
303	    const bool primary = m_style == HeaderStyle::PrimaryLeft || m_style == HeaderStyle::PrimaryRight;
304	    const bool chip    = m_style == HeaderStyle::ChipLeft || m_style == HeaderStyle::ChipRight;
305	    dc.SetBackground(wxBrush(m_style == HeaderStyle::Menu ? p.surface_raised : p.surface_canvas));
306	    dc.Clear();
307	    wxGraphicsContext* gc = &context;
308	
309	    const auto foreground = !IsEnabled() ? p.action_disabled_text :
310	                            m_decoration.danger ? p.status_danger :
311	                            primary ? p.action_primary_text :
312	                            m_style == HeaderStyle::Quiet ? p.text_secondary : p.text_primary;
313	    const bool highlighted = (m_hover || m_open || m_menu_selected) && IsEnabled();
314	    wxColour fill = primary ? (!IsEnabled() ? p.action_disabled : m_pressed || m_open ? p.action_primary_pressed :
315	                              m_hover ? p.action_primary_hover : p.action_primary) :
316	                   highlighted ? p.surface_selected :
317	                   // The spool half sits on a quieter ground than the printer
318	                   // half, so the chip reads as two things inside one outline.
319	                   m_style == HeaderStyle::ChipRight ? p.surface_subtle :
320	                   m_style == HeaderStyle::Menu ? p.surface_raised : p.surface_canvas;
321	
322	    const ShellMetrics& m = m_theme.metrics();
323	    const double w = client.x, h = client.y;
324	    const double r = FromDIP(primary ? m.radius_compact :
325	                             chip ? m.chip.radius :
326	                             m_style == HeaderStyle::Menu ? m.menu_row.radius :
327	                             m_style == HeaderStyle::Outline ? m.button.icon.radius : m.radius_standard);
328	    if (chip) {
329	        // Each half draws the whole chip's rounded rectangle, extended past
330	        // the shared inner edge so only its own outer corners round. The top
331	        // and bottom borders then meet exactly across the seam.
332	        gc->SetPen(wxPen(p.border_subtle));
333	        gc->SetBrush(wxBrush(fill));
334	        gc->DrawRoundedRectangle(m_style == HeaderStyle::ChipLeft ? 0.5 : 0.5 - r, 0.5, w - 1 + r, h - 1, r);
335	        if (m_style == HeaderStyle::ChipRight) {
336	            gc->SetPen(wxPen(p.border_subtle));
337	            gc->StrokeLine(0.5, 0.5, 0.5, h - 0.5);
338	        }
339	    } else {
340	        gc->SetPen(primary || m_style == HeaderStyle::Quiet || m_style == HeaderStyle::Menu ? *wxTRANSPARENT_PEN : wxPen(p.border_subtle));
341	        gc->SetBrush(wxBrush(fill));
342	        gc->DrawRoundedRectangle(0.5,0.5,w-1,h-1,r);
343	    }
344	    if (primary && (m_style == HeaderStyle::PrimaryRight || m_attached)) {
345	        gc->SetPen(*wxTRANSPARENT_PEN);
346	        gc->DrawRectangle(m_style == HeaderStyle::PrimaryLeft ? w-r-1 : 0,0,r+1,h);
347	    }
348	    if (m_style == HeaderStyle::PrimaryRight) {
349	        gc->SetPen(wxPen(p.action_primary_hover));
350	        gc->StrokeLine(0,FromDIP(7),0,h-FromDIP(7));
351	    }
352	
353	    const double icon_size = FromDIP(m.button.icon.icon_size);
354	    const HeaderIcon icon = m_open && m_icon == HeaderIcon::Down ? HeaderIcon::Up : m_icon;
355	    if (m_style == HeaderStyle::PrimaryRight || m_style == HeaderStyle::Outline) {
356	        draw_icon(*gc, icon, (w-icon_size)/2,(h-icon_size)/2,icon_size,foreground);
357	        if (HasFocus()) {
358	            gc->SetBrush(*wxTRANSPARENT_BRUSH); gc->SetPen(wxPen(p.border_focus,FromDIP(2)));
359	            gc->DrawRoundedRectangle(2,2,w-4,h-4,std::max(0.,r-2));
360	        }
361	        return;
362	    }
363	
364	    double x = FromDIP(12);
365	    if (icon != HeaderIcon::None) {
366	        draw_icon(*gc,icon,x,(h-icon_size)/2,icon_size,foreground);
367	        x += FromDIP(24);
368	    }
369	    if (m_decoration.dot.has_value()) {
370	        const double dot = FromDIP(8);
371	        draw_dot(*gc, m_decoration.dot, x, (h-dot)/2, dot, p);
372	        x += FromDIP(16);
373	    }
374	
375	    // Right edge inward: trailing glyph, check, status, detail. Each consumes
376	    // its slot so the label knows exactly how much room is left.
377	    double right = w - FromDIP(12);
378	    if (m_row_action != HeaderIcon::None) {
379	        // Revealed on hover or keyboard selection; the slot is always
380	        // reserved, so rows do not shift when the pointer crosses them.
381	        if (highlighted) {
382	            const wxRect rect = row_action_rect();
383	            draw_icon(*gc, m_row_action, rect.x + (rect.width-icon_size)/2, rect.y + (rect.height-icon_size)/2,
384	                      icon_size, p.text_secondary);
385	        }
386	        right -= FromDIP(20);
387	    }
388	    if (m_decoration.trailing != HeaderIcon::None) {
389	        draw_icon(*gc, m_decoration.trailing, right-icon_size, (h-icon_size)/2, icon_size, p.text_secondary);
390	        right -= FromDIP(20);
391	    }
392	    if (m_decoration.check) {
393	        draw_icon(*gc, HeaderIcon::Check, right-icon_size, (h-icon_size)/2, icon_size, p.action_primary);
394	        right -= FromDIP(20);
395	    }
396	    if (!m_decoration.detail.empty() && !m_decoration.detail_inline) {
397	        gc->SetFont(detail_font(), p.text_secondary);
398	        double tw,th; gc->GetTextExtent(m_decoration.detail,&tw,&th);
399	        gc->DrawText(m_decoration.detail, right-tw, (h-th)/2);
400	        right -= tw + FromDIP(16);
401	    }
402	    if (m_decoration.status != StatusTone::None) {
403	        if (!m_decoration.status_word.empty()) {
404	            gc->SetFont(m_theme.font(TextRole::Label), p.text_secondary);
405	            double tw,th; gc->GetTextExtent(m_decoration.status_word,&tw,&th);
406	            gc->DrawText(m_decoration.status_word, right-tw, (h-th)/2);
407	            right -= tw + FromDIP(4);
408	        }
409	        const double dot = FromDIP(6);
410	        const wxColour tone = status_colour(m_decoration.status, p);
411	        if (m_decoration.status == StatusTone::Neutral) {
412	            // "Not connected" is an absence, not a state: a dashed ring says
413	            // so without borrowing a status colour.
414	            gc->SetPen(wxPen(tone, 1, wxPENSTYLE_SHORT_DASH));
415	            gc->SetBrush(*wxTRANSPARENT_BRUSH);
416	        } else {
417	            gc->SetPen(*wxTRANSPARENT_PEN);
418	            gc->SetBrush(wxBrush(tone));
419	        }
420	        gc->DrawEllipse(right-dot, h/2-dot/2, dot, dot);
421	        right -= FromDIP(14);
422	    }
423	
424	    int available = std::max(0, int(right - x));
425	    // An inline detail is part of the same line and must never be overrun by
426	    // the trailing glyph, so it claims its width first and the label
427	    // ellipsizes into what is left. Under pressure the name gives way and the
428	    // measurement survives, which is the useful half of "X1 Carbon \xC2\xB7 0.4".
429	    double inline_run = 0;
430	    if (!m_decoration.detail.empty() && m_decoration.detail_inline) {
431	        dc.SetFont(GetFont());
432	        inline_run = dc.GetTextExtent(wxString::FromUTF8(" \xC2\xB7")).x + FromDIP(3);
433	        dc.SetFont(detail_font());
434	        inline_run += dc.GetTextExtent(m_decoration.detail).x;
435	        available = std::max(0, available - int(inline_run));
436	    }
437	    if (m_label_cap > 0) available = std::min(available, FromDIP(m_label_cap));
438	    dc.SetFont(GetFont());
439	    const wxString text = wxControl::Ellipsize(GetLabel(), dc, wxELLIPSIZE_END, available);
440	    gc->SetFont(GetFont(),foreground);
441	    double tw,th; gc->GetTextExtent(text,&tw,&th);
442	    const bool two_line = !m_decoration.sub_label.empty();
443	    const double label_y = two_line ? h/2 - th - FromDIP(1) : (h-th)/2;
444	    gc->DrawText(text,x,label_y);
445	    if (!m_decoration.detail.empty() && m_decoration.detail_inline) {
446	        // Separator and value continue the same line, each in its own face.
447	        // The separator carries its own leading space; the trailing gap comes
448	        // from the monospace advance, so adding one here would double it.
449	        const wxString separator = wxString::FromUTF8(" \xC2\xB7");
450	        gc->SetFont(GetFont(), p.text_secondary);
451	        double sw,sh; gc->GetTextExtent(separator,&sw,&sh);
452	        gc->DrawText(separator, x+tw, (h-sh)/2);
453	        gc->SetFont(detail_font(), p.text_secondary);
454	        double dh, dw; gc->GetTextExtent(m_decoration.detail,&dw,&dh);
455	        gc->DrawText(m_decoration.detail, x+tw+sw+FromDIP(3), (h-dh)/2);
456	    }
457	    if (two_line) {
458	        dc.SetFont(m_theme.font(TextRole::Metadata));
459	        const wxString sub = wxControl::Ellipsize(m_decoration.sub_label, dc, wxELLIPSIZE_END, available);
460	        gc->SetFont(m_theme.font(TextRole::Metadata), p.text_secondary);
461	        gc->DrawText(sub, x, h/2 + FromDIP(1));
462	    }
463	    if (m_status) {
464	        gc->SetPen(*wxTRANSPARENT_PEN);
465	        gc->SetBrush(wxBrush(m_warning ? p.status_warning : p.status_success_on_action));
466	        gc->DrawEllipse(x+tw+FromDIP(8),h/2-FromDIP(3),FromDIP(6),FromDIP(6));
467	    }
468	
469	    // Menu rows never paint a focus ring: the popup owns selection for the whole
470	    // list, so a row holding native focus is an artifact, not a selected row.
471	    if (HasFocus() && m_style != HeaderStyle::Menu) {
472	        gc->SetBrush(*wxTRANSPARENT_BRUSH); gc->SetPen(wxPen(p.border_focus,FromDIP(2)));
473	        gc->DrawRoundedRectangle(2,2,w-4,h-4,std::max(0.,r-2));
474	    }
475	}
