35	wxString option_string(const DynamicPrintConfig& config, const char* key, unsigned index = 0)
36	{
37	    if (const auto* option = config.option<ConfigOptionStrings>(key); option && option->values.size() > index)
38	        return wxString::FromUTF8(option->values[index]);
39	    return {};
40	}
