42	// The brand printed on the reel. Orca resolves filament_vendor through the
43	// inheritance chain, so a branded profile reports its own name and everything
44	// that only inherits fdm_filament_common reports "Generic". Preset::vendor
45	// cannot answer this: it names the profile bundle the preset shipped in.
46	wxString filament_vendor(const Preset& preset)
47	{
48	    const wxString vendor = option_string(preset.config, "filament_vendor");
49	    // PrintConfig's stand-in for a preset that declares no vendor at all. It is
50	    // a placeholder, not a brand, so it reads here as no vendor.
51	    return vendor == "(Undefined)" ? wxString{} : vendor;
52	}
