210	void set_filament_colour(Plater& plater, const wxColour& colour)
211	{
212	    PresetBundle* presets = wxGetApp().preset_bundle;
213	    if (presets == nullptr || !colour.IsOk())
214	        return;
215	    DynamicPrintConfig& project = presets->project_config;
216	
217	    // PlaterPresetComboBox::sync_colour_config, patching extruder 0. The three
218	    // options move together: a colour written without its type and
219	    // multi-colour siblings leaves a gradient's leftovers behind.
220	    auto patch = [&](const char* key, const std::string& value) -> ConfigOptionStrings* {
221	        auto* option = static_cast<ConfigOptionStrings*>(project.option(key)->clone());
222	        if (option->values.empty()) option->values.resize(1);
223	        option->values[0] = value;
224	        return option;
225	    };
226	    const std::string hex = colour.GetAsString(wxC2S_HTML_SYNTAX).ToStdString();
227	
228	    DynamicPrintConfig updated = project;
229	    updated.set_key_value("filament_multi_colour", patch("filament_multi_colour", hex));
230	    updated.set_key_value("filament_colour", patch("filament_colour", hex));
231	    updated.set_key_value("filament_colour_type", patch("filament_colour_type", "1")); // solid, not gradient
232	    project.apply(updated);
233	
234	    plater.update_project_dirty_from_presets();
235	    presets->export_selections(*wxGetApp().app_config);
236	    plater.on_config_change(updated);
237	
238	    auto* changed = new wxCommandEvent(EVT_FILAMENT_COLOR_CHANGED);
239	    changed->SetInt(0);
240	    wxQueueEvent(&plater, changed);
