392	wxString colour_word(const wxColour& colour)
393	{
394	    if (!colour.IsOk())
395	        return {};
396	    // Nearest swatch in plain RGB distance. This only prefills a name the
397	    // person can edit, so a simple metric is the honest amount of machinery.
398	    const Swatch* best = nullptr;
399	    double best_distance = 0.;
400	    for (const Swatch& swatch : swatches()) {
401	        const wxColour candidate(wxString::FromUTF8(swatch.hex));
402	        const double dr = colour.Red() - candidate.Red();
403	        const double dg = colour.Green() - candidate.Green();
404	        const double db = colour.Blue() - candidate.Blue();
405	        const double distance = dr * dr + dg * dg + db * db;
406	        if (best == nullptr || distance < best_distance) {
407	            best          = &swatch;
408	            best_distance = distance;
409	        }
410	    }
411	    // Roughly a quarter of the diagonal of the RGB cube: past that, no word
412	    // describes the colour better than none.
413	    constexpr double kTooFar = 110. * 110. * 3.;
414	    if (best == nullptr || best_distance > kTooFar)
415	        return {};
416	    return _(best->name);
417	}
