#pragma once

// What the right half of the printer/filament chip says about the project's
// filament slots: one dot per slot, then a label.
//
// Kept apart from the widget so the rules -- which dots are full, which fade,
// when unused slots fold into "+n", when the label names a filament and when
// it counts them -- are plain data that tests can read without wx or Orca.

#include <cstddef>
#include <string>
#include <vector>

namespace Slic3r::GUI::JusPrin {

// One project slot, as the chip needs it.
struct ChipSlot
{
    std::string preset; // the filament preset; slots sharing one print the same filament
    std::string name;   // its short name
    std::string colour; // "#RRGGBB", or empty
    bool        used{false};
};

struct ChipDot
{
    std::size_t slot{0}; // 0-based
    std::string colour;
    bool        faded{false};
};

struct FilamentChipModel
{
    // In slot order.
    std::vector<ChipDot> dots;
    // Unused slots folded into a grey "+n" after the dots; zero draws nothing.
    std::size_t folded{0};
    // More slots in use than fit at full size: every one keeps its dot, and
    // the dots shrink.
    bool small{false};
    // The short name when the slots in use share one filament; empty when the
    // label is a count instead.
    std::string name;
    // How many different filaments the slots in use print with.
    std::size_t filaments{0};
};

// Up to this many dots draw at full size.
constexpr std::size_t kFullSizeDots = 8;

// A plate with nothing on it uses no slot, and a chip of faded dots over a
// count would say nothing about the project. Every slot then reads as in use.
FilamentChipModel describe_filament_chip(const std::vector<ChipSlot>& slots);

} // namespace Slic3r::GUI::JusPrin

#include "FilamentChipModel.hpp"

#include <algorithm>
#include <set>

namespace Slic3r::GUI::JusPrin {

FilamentChipModel describe_filament_chip(const std::vector<ChipSlot>& slots)
{
    FilamentChipModel model;
    const bool nothing_used = std::none_of(slots.begin(), slots.end(), [](const ChipSlot& slot) { return slot.used; });
    const auto in_use       = [&](const ChipSlot& slot) { return nothing_used || slot.used; };

    std::set<std::string> filaments;
    std::size_t           used = 0;
    for (const ChipSlot& slot : slots)
        if (in_use(slot)) {
            filaments.insert(slot.preset);
            ++used;
        }
    model.filaments = filaments.size();
    if (model.filaments == 1)
        for (const ChipSlot& slot : slots)
            if (in_use(slot)) {
                model.name = slot.name;
                break;
            }

    // Past the full-size count, unused slots give up their dots first; the
    // slots the plate prints with always keep theirs.
    const bool fold = slots.size() > kFullSizeDots;
    for (std::size_t index = 0; index < slots.size(); ++index) {
        const bool active = in_use(slots[index]);
        if (fold && !active) {
            ++model.folded;
            continue;
        }
        model.dots.push_back({index, slots[index].colour, !active});
    }
    model.small = used > kFullSizeDots;
    return model;
}

} // namespace Slic3r::GUI::JusPrin

#include <catch2/catch_test_macros.hpp>

#include "slic3r/GUI/JusPrin/Shell/FilamentChipModel.hpp"

using namespace Slic3r::GUI::JusPrin;

namespace {

ChipSlot slot(const std::string& preset, const std::string& colour, bool used)
{
    return ChipSlot{preset, preset + " short", colour, used};
}

} // namespace

TEST_CASE("one slot names its filament and draws one full dot", "[filament_chip]")
{
    const auto model = describe_filament_chip({slot("Prusament PLA", "#F2754E", true)});
    CHECK(model.name == "Prusament PLA short");
    CHECK(model.filaments == 1);
    REQUIRE(model.dots.size() == 1);
    CHECK_FALSE(model.dots[0].faded);
    CHECK(model.dots[0].colour == "#F2754E");
    CHECK(model.folded == 0);
    CHECK_FALSE(model.small);
}

TEST_CASE("slots the plate does not use keep their dot, faded", "[filament_chip]")
{
    const auto model = describe_filament_chip({slot("PLA", "#111111", true), slot("PLA", "#222222", false),
                                               slot("PLA", "#333333", false), slot("PETG", "#444444", false)});
    // One filament in use: the label names it, whatever the unused slots hold.
    CHECK(model.name == "PLA short");
    CHECK(model.filaments == 1);
    REQUIRE(model.dots.size() == 4);
    CHECK_FALSE(model.dots[0].faded);
    CHECK(model.dots[1].faded);
    CHECK(model.dots[3].faded);
}

TEST_CASE("used slots that share one filament name it; different ones count", "[filament_chip]")
{
    SECTION("three used, one filament")
    {
        const auto model = describe_filament_chip({slot("PLA", "#1", true), slot("PLA", "#2", true),
                                                   slot("PLA", "#3", true), slot("PETG", "#4", false)});
        CHECK(model.name == "PLA short");
        CHECK(model.filaments == 1);
    }
    SECTION("three used, three filaments")
    {
        const auto model = describe_filament_chip({slot("PLA", "#1", true), slot("PETG", "#2", true),
                                                   slot("ABS", "#3", true), slot("TPU", "#4", false)});
        CHECK(model.name.empty());
        CHECK(model.filaments == 3);
    }
    SECTION("two slots of one filament and one of another count filaments, not slots")
    {
        const auto model = describe_filament_chip({slot("PLA", "#1", true), slot("PLA", "#2", true),
                                                   slot("PETG", "#3", true)});
        CHECK(model.name.empty());
        CHECK(model.filaments == 2);
    }
}

TEST_CASE("an empty plate reads every slot as in use", "[filament_chip]")
{
    const auto model = describe_filament_chip({slot("PLA", "#1", false), slot("PETG", "#2", false)});
    CHECK(model.filaments == 2);
    REQUIRE(model.dots.size() == 2);
    CHECK_FALSE(model.dots[0].faded);
    CHECK_FALSE(model.dots[1].faded);
}

TEST_CASE("past eight slots unused ones fold into +n and used ones keep their dots", "[filament_chip]")
{
    std::vector<ChipSlot> slots;
    for (int i = 0; i < 12; ++i)
        slots.push_back(slot(i % 2 ? "PETG" : "PLA", "#" + std::to_string(i), i == 1 || i == 4 || i == 9));
    const auto model = describe_filament_chip(slots);
    CHECK(model.folded == 9);
    REQUIRE(model.dots.size() == 3);
    CHECK(model.dots[0].slot == 1);
    CHECK(model.dots[1].slot == 4);
    CHECK(model.dots[2].slot == 9);
    CHECK_FALSE(model.small);
}

TEST_CASE("more than eight used slots all keep a dot, and the dots shrink", "[filament_chip]")
{
    std::vector<ChipSlot> slots;
    for (int i = 0; i < 12; ++i)
        slots.push_back(slot("PLA" + std::to_string(i), "#" + std::to_string(i), true));
    const auto model = describe_filament_chip(slots);
    CHECK(model.dots.size() == 12);
    CHECK(model.folded == 0);
    CHECK(model.small);
    CHECK(model.filaments == 12);
}

TEST_CASE("exactly eight slots draw every dot at full size", "[filament_chip]")
{
    std::vector<ChipSlot> slots;
    for (int i = 0; i < 8; ++i)
        slots.push_back(slot("PLA", "#" + std::to_string(i), i == 0));
    const auto model = describe_filament_chip(slots);
    CHECK(model.dots.size() == 8);
    CHECK(model.folded == 0);
    CHECK_FALSE(model.small);
}

