2939	    // Drives the two-click swap without a pointer: open the half, pick a row
2940	    // that is not the current spool, and confirm the chip followed.
2941	    // Writes the chip as it actually renders, in both appearance modes and in
2942	    // the long-name case, so appearance is evidence rather than a claim. The
2943	    // application draws these itself, so they need no screen-capture
2944	    // permission and do not depend on what else is on the tester's display.
2945	    void capture_chip_appearance()
2946	    {
2947	        auto* row  = installed_shell()->status_row();
2948	        auto* chip = dynamic_cast<PrinterSpoolChip*>(wxWindow::FindWindowByName("Printer and spool", row));
2949	        check(chip != nullptr, "chip_is_in_the_header");
2950	        if (chip == nullptr) return;
2951	
2952	        // The automated run's data directory is temporary and removed at exit.
2953	        // JUSPRIN_ARTIFACT_DIR keeps the images for a human to look at.
2954	        const char* artifact_dir = std::getenv("JUSPRIN_ARTIFACT_DIR");
2955	        const fs::path out = artifact_dir != nullptr ? fs::path(artifact_dir)
2956	                                                     : fs::path(data_dir()) / "chip-appearance";
2957	        fs::create_directories(out);
2958	        const bool was_dark = wxGetApp().dark_mode();
2959	        // At rest means no menu open AND no focus ring: either one makes these
2960	        // images describe a state the reader does not see when simply looking
2961	        // at the header. Earlier checks leave a half focused, and a popup that
2962	        // is still dismissing hands focus back to its anchor after it goes --
2963	        // so drain those pending events first, then move focus away
2964	        // unconditionally rather than testing where it happens to be.
2965	        // The assertion below reads HasFocus(), the same predicate the painter
2966	        // uses to draw the ring, so it cannot disagree with the image. macOS
2967	        // grants focus only inside the key window, so it can only fire on a run
2968	        // where this app is frontmost -- which is the run that would otherwise
2969	        // write a chip with a ring on it.
2970	        wxYield();
2971	        // Focus has to land on a window that can actually hold it, and that is
2972	        // not the row: wxPanel::SetFocus() forwards to a child -- on Windows,
2973	        // one of the very chip halves this is clearing -- and
2974	        // SetFocusIgnoringChildren() on a panel that is not itself focusable
2975	        // leaves focus exactly where it was. Either way the ring the next line
2976	        // asserts against would be the one this line drew. The canvas takes
2977	        // focus on every platform and is not part of the header being
2978	        // photographed.
2979	        m_plater->canvas3D()->get_wxglcanvas()->SetFocus();
2980	        wxYield();
2981	        check(!chip_half_open(), "chip_is_at_rest_before_capture");
2982	        check(!chip->printer_half().HasFocus() && !chip->spool_half().HasFocus(),
2983	              "no_focus_ring_when_the_chip_is_captured");
2984	
2985	        // Deliberately does NOT refresh: a refresh re-reads the spool store and
2986	        // would overwrite any label the caller set for the shot.
2987	        auto write = [&](const std::string& name) {
2988	            chip->Layout();
2989	            const wxBitmap bitmap = chip->snapshot();
2990	            const std::string file = (out / (name + ".png")).string();
2991	            const bool ok = bitmap.IsOk() && bitmap.GetWidth() > 0 &&
2992	                            bitmap.ConvertToImage().SaveFile(wxString::FromUTF8(file), wxBITMAP_TYPE_PNG);
2993	            check(ok, "chip_renders_" + name);
2994	            if (ok) std::cout << "HARNESS ARTIFACT " << name << " " << file
2995	                              << " " << bitmap.GetWidth() << "x" << bitmap.GetHeight() << std::endl;
2996	            return bitmap.IsOk() ? bitmap.ConvertToImage() : wxImage();
2997	        };
2998	        auto same_pixels = [](const wxImage& a, const wxImage& b) {
2999	            if (!a.IsOk() || !b.IsOk() || a.GetWidth() != b.GetWidth() || a.GetHeight() != b.GetHeight())
3000	                return false;
3001	            return std::memcmp(a.GetData(), b.GetData(), std::size_t(a.GetWidth()) * a.GetHeight() * 3) == 0;
3002	        };
3003	
3004	        row->refresh();
3005	        installed_shell()->status_row()->apply_appearance(false);
3006	        const wxImage light = write("light");
3007	        installed_shell()->status_row()->apply_appearance(true);
3008	        const wxImage dark = write("dark");
3009	        // Dark mode is a real remapping, not the same pixels with a filter.
3010	        check(!same_pixels(light, dark), "light_and_dark_render_differently");
3011	
3012	        // A name far past the 240 DIP cap must ellipsize rather than widen the
3013	        // chip. No refresh after this point: it would restore the real name.
3014	        installed_shell()->status_row()->apply_appearance(false);
3015	        const int natural = chip->GetBestSize().x;
3016	        chip->set_spool("Prusament Galaxy Black PLA Blend, third reel from the shelf by the window",
3017	                        wxColour("#101010"));
3018	        chip->InvalidateBestSize();
3019	        const int capped = chip->GetBestSize().x;
3020	        const wxImage long_name = write("long-name");
3021	        // The proof the long name was actually rendered: different pixels.
3022	        check(!same_pixels(light, long_name), "long_name_actually_rendered");
3023	        // 240 DIP label cap plus the half's own padding and chevron; a name
3024	        // this long must not push the chip past that.
3025	        check(capped <= chip->FromDIP(240) + natural, "long_spool_name_stays_within_the_cap");
3026	        std::cout << "HARNESS MEASURE chip_natural_width=" << natural
3027	                  << " chip_capped_width=" << capped << std::endl;
3028	
3029	        // Leave the chip showing real state again.
3030	        installed_shell()->status_row()->apply_appearance(was_dark);
3031	        row->refresh();
3032	    }
