    {
        auto* row = dynamic_cast<HeaderButton*>(wxWindow::FindWindowByName(name, menu));
        if (row == nullptr || !row->IsEnabled()) return nullptr;
        click_row(menu, row);
        wxYield();
        return visible_header_menu();
    }

