                   if (menu) menu->close();
                   self->finish();
               });
}

// Polls, from inside whatever modal loop is running, for the dialog the
// sync row opens, and cancels it.
void watch_for_sync_dialog(int tries_left)
{
    for (wxWindow* window : wxTopLevelWindows)
        if (auto* dialog = dynamic_cast<wxDialog*>(window); dialog && dialog->IsModal()) {
            m_sync_dialog_seen = std::string(dynamic_cast<SyncAmsInfoDialog*>(dialog) ? "SyncAmsInfoDialog" : "other") +
                                 " title=" + ui_text(dialog->GetTitle());
            dialog->EndModal(wxID_CANCEL);
            return;
        }
    if (tries_left <= 0) {
        m_sync_dialog_seen = "none";
        return;
    }
    wxGetApp().CallAfter([self = shared_from_this(), tries_left] {
        std::this_thread::sleep_for(std::chrono::milliseconds(20));
        self->watch_for_sync_dialog(tries_left - 1);
    });
}

